import * as T from 'three';
import {GLTFLoader} from '../vendor/loaders/GLTFLoader.js';
import {createCitySimulation} from './city-simulation.mjs';
const cache=new Map(),loader=new GLTFLoader();
export async function createCityAdapter(seed,options={},saved){
 let sim=createCitySimulation(seed,options,saved);const plan=sim.plan,root=new T.Group();root.scale.setScalar(.1);const owned=[],actors=[];
 const ids=Array.from({length:30},(_,i)=>'RC-'+String(i+1).padStart(3,'0')).concat('GF-008');
 await Promise.all(ids.map(async id=>{if(!cache.has(id))cache.set(id,(await loader.loadAsync(new URL('./assets/'+id+'.glb',import.meta.url).href)).scene);}));
 function model(id){const o=cache.get(id).clone(true);o.traverse(m=>{if(m.isMesh){m.castShadow=m.receiveShadow=true;m.userData.sharedGeometry=true;for(const mat of Array.isArray(m.material)?m.material:[m.material])mat.userData.shared=true;}});return o;}
 function mesh(g,color){const m=new T.Mesh(g,new T.MeshStandardMaterial({color,roughness:.95}));owned.push(m);m.receiveShadow=true;return m;}
 function place(id,x,z,y=0,rotation=0){const o=model(id);o.position.set(x,y,z);o.rotation.y=rotation;root.add(o);return o;}
 const terrain=mesh(new T.CylinderGeometry(plan.radius,plan.radius,1.2,6),'#94816e');terrain.position.y=-.6;root.add(terrain);
 for(const r of plan.roads){const road=mesh(new T.RingGeometry(r-2,r+2,96),'#4c4252');road.rotation.x=-Math.PI/2;road.position.y=.035;root.add(road);const curb=mesh(new T.RingGeometry(r+2,r+4,96),'#b5a08a');curb.rotation.x=-Math.PI/2;curb.position.y=.045;root.add(curb);}
 for(let i=0;i<16;i+=4){const a=plan.turn+i*Math.PI/8,o=mesh(new T.BoxGeometry(4,.06,plan.roads.length===2?38:20),'#4c4252');o.position.set(Math.sin(a)*(plan.roads.length===2?18:10),.04,Math.cos(a)*(plan.roads.length===2?18:10));o.rotation.y=a;root.add(o);}
 const plaza=mesh(new T.CylinderGeometry(12,12,.12,48),'#c3a883');plaza.position.y=.04;root.add(plaza);
 for(const p of plan.placements){const o=place(p.asset,p.x,p.z,.12,p.rotation);o.userData.inspect={title:p.label,kind:'Retro city · '+p.role,description:'Generated street frontage. Building geometry is registered in the asset workshop.'};o.userData.liveReadout=()=>{const site=sim.state.sites.find(s=>s.id===p.id);return site?`${site.parcels.toFixed(0)} parcels · ${site.visits} deliveries`:p.role==='depot'?`${sim.state.stock.parcels.toFixed(0)} parcels remaining`:'Public observatory · no research economy simulated';};}
 for(let i=0;i<16;i++){const n=plan.nodes[i],a=plan.turn+i*Math.PI/8;place('RC-022',n.x*1.04,n.z*1.04);if(i%2===0)place('RC-024',n.x*.62,n.z*.62);if(i%4===1)place('RC-023',n.x*.64,n.z*.64,0,a);}
 place('RC-026',-9,1);place('RC-025',9,4);place('RC-027',0,plan.roads.length===2?37:19);place('RC-030',10,-6);
 for(let i=0;i<8;i++){const a=plan.turn+i*Math.PI/4;place('RC-029',Math.sin(a)*12,Math.cos(a)*12);}
 const airship=place('RC-021',0,0,47);airship.userData.inspect={title:'Commuter airship',kind:'Ambient traffic',description:'An animated flight circuit, not passenger transport simulation.'};
 const cars=Array.from({length:6},(_,i)=>place('RC-'+String(18+i%3).padStart(3,'0'),0,0));
 for(const person of [...sim.workers,...sim.residents]){const body=place('GF-008',person.position.x,person.position.z,.12);body.userData.inspect={title:person.name,kind:person.id.startsWith('courier')?'Parcel courier':'Resident',description:person.id.startsWith('courier')?'Moves real finite parcel stock between depot and buildings.':'Walks between connected street destinations; visits are spatial activity.'};actors.push({id:person.id,body,get phase(){return [...sim.workers,...sim.residents].find(p=>p.id===person.id).phase;}});}
 function present(){for(const a of actors){const p=[...sim.workers,...sim.residents].find(p=>p.id===a.id);a.body.position.set(p.position.x,.12,p.position.z);a.body.rotation.y=p.heading||0;a.body.userData.activity=p.phase;a.body.userData.liveReadout=()=>p.job?`${p.phase} · ${p.job.load} parcels in hand`:`${p.phase} · ${p.visits||0} visits`;}const t=sim.state.seconds;for(const [i,c]of cars.entries()){const a=t*.035+i*Math.PI/3,r=plan.roads[i%plan.roads.length];c.position.set(Math.sin(a)*r,.1,Math.cos(a)*r);c.rotation.y=a+Math.PI/2;}airship.position.set(Math.sin(t*.008)*plan.radius*.65,46,Math.cos(t*.008)*plan.radius*.55);airship.rotation.y=t*.008+Math.PI/2;}
 present();const life={get state(){return sim.state;},workers:actors,places:plan.placements,update(dt){sim.update(Math.min(60,dt));present();},snapshot:()=>sim.snapshot(),restore(s){sim=createCitySimulation(seed,options,s);present();},summary:()=>({animals:0,buildings:plan.placements.length,residents:sim.residents.length+sim.workers.length,delivered:sim.state.delivered.parcels,jobs:sim.state.jobs,stock:sim.state.stock.parcels}),navigation:()=>({workers:sim.workers.map(w=>({...w.position,phase:w.phase})),connected:true}),notices:()=>sim.state.stock.parcels===0?[{text:'Depot empty. This city has finite parcel stock; regeneration creates a new supply.'}]:[],dispose:()=>sim.dispose(),get readout(){return `${sim.state.stock.parcels.toFixed(0)} depot parcels · ${sim.state.delivered.parcels.toFixed(0)} delivered · ${sim.state.jobs} completed deliveries`;}};
 return {group:root,plan,life,heightAt:()=>0,recipe:{name:'Sunset Metropolis '+seed,seed,tiles:[]},assembly:{plans:[{id:'city-1',placements:plan.placements,paths:plan.edges,plantedAssets:[]}]},tileObjects:[],fitBounds:new T.Box3(new T.Vector3(-plan.radius*.1,-.12,-plan.radius*.1),new T.Vector3(plan.radius*.1,5.1,plan.radius*.1)),dispose(){for(const o of owned){o.geometry.dispose();o.material.dispose();}}};
}
